import{u as s,o as e,c as n,a2 as i}from"./chunks/framework.DZhUhjDB.js";const c=JSON.parse('{"title":"Phishing: cómo detectar y prevenir el ataque más efectivo","description":"Tipos de phishing, técnicas de detección y herramientas de protección","frontmatter":{"title":"Phishing: cómo detectar y prevenir el ataque más efectivo","description":"Tipos de phishing, técnicas de detección y herramientas de protección","author":"Equipo CDPN","date":"2026-08-03T00:00:00.000Z","tags":["phishing","ingenieria-social","seguridad","prevencion"],"readingTime":"5 min"},"headers":[],"relativePath":"blog/10-phishing-ingenieria-social.md","filePath":"blog/10-phishing-ingenieria-social.md","lastUpdated":null}'),l={name:"blog/10-phishing-ingenieria-social.md"},d=Object.assign(l,{setup(t){const{frontmatter:r}=s();return(o,a)=>(e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="phishing-como-detectar-y-prevenir-el-ataque-mas-efectivo" tabindex="-1">Phishing: cómo detectar y prevenir el ataque más efectivo <a class="header-anchor" href="#phishing-como-detectar-y-prevenir-el-ataque-mas-efectivo" aria-label="Permalink to &quot;Phishing: cómo detectar y prevenir el ataque más efectivo&quot;">​</a></h1><div class="article-meta"><span class="accent">📝 Equipo CDPN</span><span>📅 3 Agosto 2026</span><span>📖 5 min de lectura</span><span>🏷️ Phishing</span><span>🏷️ Ingeniería Social</span></div><h2 id="¿que-es-el-phishing" tabindex="-1">¿Qué es el Phishing? <a class="header-anchor" href="#¿que-es-el-phishing" aria-label="Permalink to &quot;¿Qué es el Phishing?&quot;">​</a></h2><p><strong>Phishing</strong> es una técnica de ingeniería social donde el atacante se hace pasar por una entidad confiable para engañar a la víctima y robar información sensible (credenciales, datos bancarios, etc.).</p><h3 id="datos-que-asustan" tabindex="-1">Datos que asustan <a class="header-anchor" href="#datos-que-asustan" aria-label="Permalink to &quot;Datos que asustan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Dato</th><th>Cifra</th></tr></thead><tbody><tr><td>Ataques de phishing en 2025</td><td><strong>3.4 mil millones/día</strong></td></tr><tr><td>Empresas víctimas de phishing</td><td><strong>74%</strong></td></tr><tr><td>Coste promedio de un breach por phishing</td><td><strong>$4.9 millones</strong></td></tr><tr><td>Phishing como vector de breach</td><td><strong>16% de todos los breaches</strong></td></tr></tbody></table><h2 id="tipos-de-phishing" tabindex="-1">Tipos de phishing <a class="header-anchor" href="#tipos-de-phishing" aria-label="Permalink to &quot;Tipos de phishing&quot;">​</a></h2><h3 id="_1-email-phishing-el-clasico" tabindex="-1">1. Email Phishing (el clásico) <a class="header-anchor" href="#_1-email-phishing-el-clasico" aria-label="Permalink to &quot;1. Email Phishing (el clásico)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>De: soporte@banco-seguro.com (dominio falso)</span></span>
<span class="line"><span>Asunto: ⚠️ Tu cuenta ha sido comprometida</span></span>
<span class="line"><span>Body: Haz clic aquí para verificar tu identidad</span></span>
<span class="line"><span>→ Te lleva a una web falsa que roba tus credenciales</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-spear-phishing-dirigido" tabindex="-1">2. Spear Phishing (dirigido) <a class="header-anchor" href="#_2-spear-phishing-dirigido" aria-label="Permalink to &quot;2. Spear Phishing (dirigido)&quot;">​</a></h3><ul><li>El atacante <strong>investiga a la víctima</strong> (LinkedIn, redes sociales)</li><li>Personaliza el mensaje con datos reales (nombre, empresa, cargo)</li><li><strong>Tasa de éxito: 10x mayor</strong> que el phishing genérico</li></ul><h3 id="_3-whaling-objetivos-de-alto-valor" tabindex="-1">3. Whaling (objetivos de alto valor) <a class="header-anchor" href="#_3-whaling-objetivos-de-alto-valor" aria-label="Permalink to &quot;3. Whaling (objetivos de alto valor)&quot;">​</a></h3><ul><li>Dirigido a <strong>C-levels</strong> (CEO, CFO, CISO)</li><li>Suele suplantar a un abogado, socio o regulador</li><li>Incluye documentos oficiales falsos</li></ul><h3 id="_4-smishing-vishing" tabindex="-1">4. Smishing / Vishing <a class="header-anchor" href="#_4-smishing-vishing" aria-label="Permalink to &quot;4. Smishing / Vishing&quot;">​</a></h3><ul><li><strong>Smishing</strong> — Phishing vía SMS</li><li><strong>Vishing</strong> — Phishing vía teléfono (voice)</li><li>Ejemplo: &quot;Su paquete tiene un problema, pulse 1 para hablar con un agente&quot;</li></ul><h3 id="_5-clone-phishing" tabindex="-1">5. Clone Phishing <a class="header-anchor" href="#_5-clone-phishing" aria-label="Permalink to &quot;5. Clone Phishing&quot;">​</a></h3><ul><li>Copia exacta de un email legítimo que la víctima recibió</li><li>Reemplaza el enlace/adjunto con uno malicioso</li><li>Muy difícil de detectar a simple vista</li></ul><h2 id="como-detectar-phishing" tabindex="-1">Cómo detectar phishing <a class="header-anchor" href="#como-detectar-phishing" aria-label="Permalink to &quot;Cómo detectar phishing&quot;">​</a></h2><h3 id="checklist-de-seguridad" tabindex="-1">Checklist de seguridad <a class="header-anchor" href="#checklist-de-seguridad" aria-label="Permalink to &quot;Checklist de seguridad&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>☐ El remitente es exactamente quién dice ser?</span></span>
<span class="line"><span>   → soporte@google.com ≠ soporte@g00gle.com</span></span>
<span class="line"><span>☐ El enlace apunta al dominio correcto?</span></span>
<span class="line"><span>   → Pasa el cursor por encima, NO hagas clic</span></span>
<span class="line"><span>☐ Hay urgencia artificial?</span></span>
<span class="line"><span>   → &quot;Tu cuenta será cerrada en 24 horas&quot;</span></span>
<span class="line"><span>☐ Errores ortográficos o gramaticales?</span></span>
<span class="line"><span>   → Empresas reales revisan sus emails</span></span>
<span class="line"><span>☐ Te piden datos sensibles por email?</span></span>
<span class="line"><span>   → Ninguna empresa legítima hace esto</span></span>
<span class="line"><span>☐ El email usa attachments inusuales?</span></span>
<span class="line"><span>   → .html, .js, .zip sospechosos</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h3 id="verificar-el-dominio" tabindex="-1">Verificar el dominio <a class="header-anchor" href="#verificar-el-dominio" aria-label="Permalink to &quot;Verificar el dominio&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verificar dominio real detrás de un enlace</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. No hagas clic — copia el enlace</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Usa un URL analyzer</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Herramientas gratuitas:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - urlscan.io — Análisis completo</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - virustotal.com — Verificación de malware</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># - phishtank.com — Base de datos de phishing</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="analizar-headers-del-email" tabindex="-1">Analizar headers del email <a class="header-anchor" href="#analizar-headers-del-email" aria-label="Permalink to &quot;Analizar headers del email&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># En Gmail: Ver original del email</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Busca: &quot;Received:&quot; headers</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># El primer &quot;Received:&quot; es el servidor real que envió el email</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ejemplo de header falso:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Received: from mail.banco.com (192.168.1.1)  ← SERVIDOR REAL</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Received: from mx.banco-seguro.com             ← DOMINIO FALSO</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="herramientas-anti-phishing" tabindex="-1">Herramientas anti-phishing <a class="header-anchor" href="#herramientas-anti-phishing" aria-label="Permalink to &quot;Herramientas anti-phishing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Herramienta</th><th>Tipo</th><th>Uso</th></tr></thead><tbody><tr><td><strong>Pi-hole</strong></td><td>DNS Filtering</td><td>Bloquear dominios maliciosos</td></tr><tr><td><strong>uBlock Origin</strong></td><td>Browser extension</td><td>Bloquear popups y redirects</td></tr><tr><td><strong>PhishTool</strong></td><td>Análisis de emails</td><td>Análisis automático de phishing</td></tr><tr><td><strong>GoPhish</strong></td><td>Simulación</td><td>Enviar campañas de phishing simulado</td></tr><tr><td><strong>DMARC/DKIM/SPF</strong></td><td>Email auth</td><td>Verificar autenticidad de emails</td></tr></tbody></table><h2 id="prevencion-para-organizaciones" tabindex="-1">Prevención para organizaciones <a class="header-anchor" href="#prevencion-para-organizaciones" aria-label="Permalink to &quot;Prevención para organizaciones&quot;">​</a></h2><h3 id="_1-capacitacion-continua" tabindex="-1">1. Capacitación continua <a class="header-anchor" href="#_1-capacitacion-continua" aria-label="Permalink to &quot;1. Capacitación continua&quot;">​</a></h3><ul><li>Simulacros de phishing trimestrales</li><li>Consequences para quienes fallan repetidamente</li><li>Gamificación: recompensar a quienes detectan phishing</li></ul><h3 id="_2-autenticacion-de-email" tabindex="-1">2. Autenticación de email <a class="header-anchor" href="#_2-autenticacion-de-email" aria-label="Permalink to &quot;2. Autenticación de email&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Configurar DMARC, DKIM y SPF en tu dominio</span></span>
<span class="line"><span># Esto impide que otros envíen emails como tú</span></span>
<span class="line"><span></span></span>
<span class="line"><span># SPF: &quot;Solo estos servidores pueden enviar emails por mi dominio&quot;</span></span>
<span class="line"><span># DKIM: &quot;Los emails legítimos tienen esta firma digital&quot;</span></span>
<span class="line"><span># DMARC: &quot;Si no pasa SPF/DKIM, rechaza o pone en cuarentena&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="_3-zero-trust-para-email" tabindex="-1">3. Zero Trust para email <a class="header-anchor" href="#_3-zero-trust-para-email" aria-label="Permalink to &quot;3. Zero Trust para email&quot;">​</a></h3><ul><li><strong>Nunca confíes</strong> en un email solo porque parece legítimo</li><li><strong>Verifica siempre</strong> por un canal separado (llamada, Slack)</li><li><strong>No hagas clic</strong> en enlaces — navega directamente al sitio</li></ul><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El phishing funciona porque <strong>explota la confianza y la urgencia</strong>, no vulnerabilities técnicas. La mejor defensa es <strong>educación + verificación constante</strong>.</p><hr><p><em>Artículo publicado en el Blog CDPN — Semana 10</em></p>`,37)])]))}});export{c as __pageData,d as default};
